pub use crate::prelude::*;

/// RFC 9457 Problem Details returned for every error response.
#[derive(Debug, Clone, Serialize, Deserialize, Default, PartialEq, Eq, Hash)]
pub struct ServiceErrorResponse {
    /// A URI reference that identifies the problem type.
    #[serde(default)]
    pub r#type: String,
    /// A short, human-readable summary of the problem type.
    #[serde(default)]
    pub title: String,
    /// The HTTP status code generated by the origin server for this occurrence of the problem.
    #[serde(default)]
    pub status: i64,
    /// A human-readable explanation specific to this occurrence of the problem.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
    /// A URI reference that identifies the specific occurrence of the problem.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub instance: Option<String>,
    /// Service-specific error code.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub code: Option<i64>,
    /// Field-level validation failures.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub errors: Option<Vec<ServiceErrorResponseErrorsItem>>,
}

impl ServiceErrorResponse {
    pub fn builder() -> ServiceErrorResponseBuilder {
        <ServiceErrorResponseBuilder as Default>::default()
    }
}

#[derive(Clone, PartialEq, Default, Debug)]
#[non_exhaustive]
pub struct ServiceErrorResponseBuilder {
    r#type: Option<String>,
    title: Option<String>,
    status: Option<i64>,
    detail: Option<String>,
    instance: Option<String>,
    code: Option<i64>,
    errors: Option<Vec<ServiceErrorResponseErrorsItem>>,
}

impl ServiceErrorResponseBuilder {
    pub fn r#type(mut self, value: impl Into<String>) -> Self {
        self.r#type = Some(value.into());
        self
    }

    pub fn title(mut self, value: impl Into<String>) -> Self {
        self.title = Some(value.into());
        self
    }

    pub fn status(mut self, value: i64) -> Self {
        self.status = Some(value);
        self
    }

    pub fn detail(mut self, value: impl Into<String>) -> Self {
        self.detail = Some(value.into());
        self
    }

    pub fn instance(mut self, value: impl Into<String>) -> Self {
        self.instance = Some(value.into());
        self
    }

    pub fn code(mut self, value: i64) -> Self {
        self.code = Some(value);
        self
    }

    pub fn errors(mut self, value: Vec<ServiceErrorResponseErrorsItem>) -> Self {
        self.errors = Some(value);
        self
    }

    /// Consumes the builder and constructs a [`ServiceErrorResponse`].
    /// This method will fail if any of the following fields are not set:
    /// - [`r#type`](ServiceErrorResponseBuilder::r#type)
    /// - [`title`](ServiceErrorResponseBuilder::title)
    /// - [`status`](ServiceErrorResponseBuilder::status)
    pub fn build(self) -> Result<ServiceErrorResponse, BuildError> {
        Ok(ServiceErrorResponse {
            r#type: self
                .r#type
                .ok_or_else(|| BuildError::missing_field("r#type"))?,
            title: self
                .title
                .ok_or_else(|| BuildError::missing_field("title"))?,
            status: self
                .status
                .ok_or_else(|| BuildError::missing_field("status"))?,
            detail: self.detail,
            instance: self.instance,
            code: self.code,
            errors: self.errors,
        })
    }
}
